frappe.listview_settings['Sales Order'] = {
    add_fields: ['custom_payment_status', 'docstatus'],

    get_indicator: function(doc) {
        const status = doc.custom_payment_status || 'Draft';

        const status_map = {
            'Draft': ['Draft', 'grey'],
            'Submitted': ['Submitted', 'blue'],
            'SI Created': ['SI Created', 'blue'],
            'Outstanding Invoice': ['Outstanding Invoice', 'orange'],
            'Partial Paid': ['Outstanding Invoice', 'orange'],
            'Paid': ['Paid', 'green'],
            'Cancelled': ['Cancelled', 'red'],
        };

        return status_map[status] || [status, 'grey'];
    },

    formatters: {
        status(value, df, doc) {
            const status = doc.custom_payment_status || 'Draft';

            const color_map = {
                'Draft': 'grey',
                'SI Created': 'blue',
                'Partial Paid': 'orange',
                'Paid': 'green',
                'Cancelled': 'red',
            };
            
            const icon_map = {
                'Draft': '📝',
                'SI Created': '🧾',
                'Partial Paid': '💸',
                'Paid': '✅',
                'Cancelled': '❌',
            };

            const color = color_map[status] || 'grey';

            return `<span class="indicator-pill ${color}">
                        ${icon_map[status] || ''} ${status}
                    </span>`;
        }
    }
};
